// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract Bank{
    function supportsToken() external pure returns (bytes32){
        return(keccak256(abi.encodePacked("Nu Token")));
    }
}

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(uint256 salt) public {
        // deploy an admissible counterparty (a token-supporting caller) keyed by the fuzzed salt
        Bank bank = new Bank();
        vm.assume(salt != 0); // keep domain wide; salt only selects deployment run
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(salt)))));
        // route the call through the admissible Bank caller's address via pranking
        vm.prank(address(bank));
        c.airDrop();
        // General rule: after a successful airdrop, the (zero-balance, token-supporting) caller holds exactly 20 tokens.
        assertTrue(c.tokenBalance(address(bank)) == 20);
    }
}
